# Parse modeline
MODELINE_RE = re.compile(
    r"^\s*#\s+(?:pylama:)\s*((?:[\w_]*=[^:\n\s]+:?)+)", re.I | re.M
).search

SKIP_PATTERN = re.compile(r"# *noqa\b", re.I).search


def split_csv(value: Union[Collection[str], str]) -> Set[str]:
    """Split a comma separated string (or any collection) into a set."""
    if isinstance(value, str):
        value = value.split(",")
