from __future__ import annotations

from argparse import ArgumentParser
from importlib import import_module
from pathlib import Path
from pkgutil import walk_packages
from typing import TYPE_CHECKING, Any, Dict, Iterable, List, Optional, Type

LINTERS: Dict[str, Type[LinterV2]] = {}

if TYPE_CHECKING:
    from pylama.context import RunContext


def iter_entry_points(group: str) -> Iterable:
    """Iterate over the given entry points group."""
    try:
        from importlib.metadata import entry_points

        try:  # Python >= 3.10
            return entry_points(group=group)
        except TypeError:  # Python 3.7 - 3.9
            return entry_points().get(group, [])  # type: ignore[attr-defined]

    except ImportError:  # pragma: no cover
        from pkg_resources import iter_entry_points as iter_eps  # noqa

        return iter_eps(group)


class LinterMeta(type):
    """Register linters."""

    def __new__(mcs, name, bases, params):
        """Register linters."""
        cls: Type[LinterV2] = super().__new__(mcs, name, bases, params)
        if cls.name is not None:
            LINTERS[cls.name] = cls
        return cls


